// biome-ignore lint/suspicious/noExplicitAny: values come from the ported, untyped mockup logic
type V = any

/** On narrow screens the week grid scrolls sideways: bring the selected slot (or the first free one) into view. */
function useScrollToFirstSlot(key: string, picking: boolean) {
  const ref = useRef<HTMLDivElement>(null)
  // biome-ignore lint/correctness/useExhaustiveDependencies: key = the visible week; re-run when it or the phase changes
  useEffect(() => {
    const cal = ref.current
    if (!cal || cal.scrollWidth <= cal.clientWidth + 1) return
    const pick = (sel: string) =>
      [...cal.querySelectorAll<HTMLElement>(sel)]
        .map((el) => el.closest<HTMLElement>('.cell'))
        .filter((el): el is HTMLElement => !!el)
    const cells = pick('.slot.sel, .slot.req').length
      ? pick('.slot.sel, .slot.req')
      : pick(picking ? '.slot.free' : '.slot.mine')
    if (!cells.length) return
    const head = cal.querySelector<HTMLElement>('.tl')?.offsetWidth ?? 0
    const c = cal.getBoundingClientRect()
    const rtl = getComputedStyle(cal).direction === 'rtl'
    // the cell nearest the start edge (row order in the DOM is not column order)
    const offs = cells.map((el) => {
      const r = el.getBoundingClientRect()
      return rtl ? c.right - r.right : r.left - c.left
    })
    const off = Math.min(...offs) - head
    const delta = rtl ? -off : off
    cal.scrollLeft += delta
  }, [key, picking])
  return ref
}

